INSERT INTO changelog (title, body, created_at) VALUES
('Голос: чесні помилки ElevenLabs',
'Раніше будь-яка відмова ElevenLabs з кодом 429 показувалась як «Закінчились кредити», хоча 429 буває і коли сервіс просто перевантажений. Тепер: перевантаження — система сама пробує ще 2 рази; ліміт — показує оригінальне пояснення ElevenLabs (скільки кредитів треба і скільки лишилось) і підказку перевірити ліміт на самому ключі API (Developers → API Keys → ключ → Credit limit); проблема з ключем — так і пише.',
'2026-11-01 19:00:00');
